INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q87779', 'Battle of the Teutoburg Forest', 'The Battle of the Teutoburg Forest, also called the Varian Disaster (Latin: Clades Variana) by Roman historians, was a major battle fought between an alliance of Germanic peoples and the Roman Empire between 8 and 11 September 9 AD, possibly near modern Kalkriese. Fighting began with an ambush by the Germanic alliance on three Roman legions being led by Publius Quinctilius Varus and their auxiliaries; the alliance was led by Arminius, a Germanic chieftain and officer of Varus''s auxilia.', 9, 9, NULL, NULL, NULL, NULL, 'month', 'September 9', 79, 'https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest'),
  ('Q630644', 'Battle of Idistaviso', 'The Battle of the Weser River, sometimes known as the First Battle of Minden or Battle of Idistaviso, was fought in 16 AD between Roman legions commanded by Roman Emperor Tiberius''s heir and adopted son, Germanicus, and an alliance of Germanic peoples, commanded by Arminius. The battle marked the end of a three-year series of campaigns by Germanicus in Germania.', 16, NULL, NULL, NULL, NULL, NULL, 'year', '16', 61, 'https://en.wikipedia.org/wiki/Battle_of_Idistaviso'),
  ('Q264737', 'Battle of Tolbiac', 'The Battle of Tolbiac was fought between the Franks, who were fighting under Clovis I, and the Alamanni, whose leader is not known. The date of the battle has traditionally been given as 496, though other accounts suggest it may either have been fought earlier, in the 480s or early 490s, or later, in 506.', 496, NULL, NULL, NULL, NULL, NULL, 'year', '496', 63, 'https://en.wikipedia.org/wiki/Battle_of_Tolbiac'),
  ('Q273069', 'Battle of Lechfeld', 'The Battle of Lechfeld, also known as the Second Battle of Lechfeld, was a series of military engagements over the course of three days from 10 to 12 August 955 in which the Kingdom of Germany, led by King Otto I the Great, defeated the Hungarian army led by Harka Bulcsú and the chieftains Lél and Súr. With the German victory, further major invasions by the Magyars into Western Europe were ended.', 955, 8, 10, NULL, NULL, NULL, 'day', '10 August 955', 71, 'https://en.wikipedia.org/wiki/Battle_of_Lechfeld'),
  ('Q152295', 'Battle of Worringen', 'The Battle of Worringen was fought on 5 June 1288 near the town of Worringen (also spelled Woeringen), which is now part of Chorweiler, the northernmost borough (Stadtbezirk) of Cologne. It was the decisive battle of the War of the Limburg Succession, fought for the possession of the Duchy of Limburg between on one side the Archbishop Siegfried II of Cologne and Count Henry VI of Luxembourg, and on the other side, Duke John I of Brabant.', 1288, 6, 5, NULL, NULL, NULL, 'day', '5 June 1288', 60, 'https://en.wikipedia.org/wiki/Battle_of_Worringen'),
  ('Q691882', 'Münster rebellion', 'The Münster rebellion (German: Täuferreich von Münster, lit. ''Anabaptist dominion of Münster'') was an attempt by radical Anabaptists to establish a communal sectarian government in the German city of Münster – then under the large Prince-Bishopric of Münster in the Holy Roman Empire. The city was under Anabaptist rule from February 1534, when the city hall was seized and Bernhard Knipperdolling installed as mayor, until its fall in June 1535.', 1534, NULL, NULL, 1535, NULL, NULL, 'year', '1534–1535', 62, 'https://en.wikipedia.org/wiki/M%C3%BCnster_rebellion'),
  ('Q661327', 'Battle of Mühlberg', 'The Battle of Mühlberg took place near Mühlberg in the Electorate of Saxony in 1547, during the Schmalkaldic War. The Catholic princes of the Holy Roman Empire led by the Holy Roman Emperor Charles V decisively defeated the Lutheran Schmalkaldic League of Protestant princes under the command of Elector John Frederick I of Saxony and Landgrave Philip I of Hesse.', 1547, 4, 25, NULL, NULL, NULL, 'day', '25 April 1547', 63, 'https://en.wikipedia.org/wiki/Battle_of_M%C3%BChlberg'),
  ('Q524189', 'Cologne War', 'The Cologne War (German: Kölner Krieg, Kölnischer Krieg, Truchsessischer Krieg; 1583–1588) was a conflict between Protestant and Catholic factions that devastated the Electorate of Cologne, a historical ecclesiastical principality of the Holy Roman Empire, within present-day North Rhine-Westphalia, in Germany. The war occurred within the context of the Protestant Reformation in Germany and the subsequent Counter-Reformation, and concurrently with the Dutch Revolt and the French Wars of Religion.', 1583, NULL, NULL, 1588, NULL, NULL, 'year', '1583–1588', 59, 'https://en.wikipedia.org/wiki/Cologne_War'),
  ('Q629302', 'Battle of Lutter', 'The Battle of Lutter (German: Lutter am Barenberge) took place on 27 August 1626 during the Thirty Years'' War, south of Salzgitter, in Lower Saxony. A combined Danish-German force led by Christian IV of Denmark was defeated by Johann Tserclaes, Count of Tilly, commanding an army of the Catholic League loyal to Emperor Ferdinand II. Christian''s campaign plan for 1626 consisted of three parts; while he led the main army against Tilly, Ernst von Mansfeld would attack Wallenstein, supported by Christian of Brunswick.', 1626, 8, 27, NULL, NULL, NULL, 'day', '27 August 1626', 61, 'https://en.wikipedia.org/wiki/Battle_of_Lutter'),
  ('Q205379', 'Battle of Breitenfeld', 'The Battle of Breitenfeld, 17 September 1631, took place during the Thirty Years'' War outside Breitenfeld, Leipzig, in modern Saxony. In one of the most significant battles of the war, a combined Swedish-Saxon force defeated an army made up of Imperial and Catholic League troops.', 1631, 9, 17, NULL, NULL, NULL, 'day', '17 September 1631', 68, 'https://en.wikipedia.org/wiki/Battle_of_Breitenfeld_(1631)'),
  ('Q167259', 'Battle of Lützen', 'The Battle of Lützen, fought on 16 November 1632, was one of the most important of the Thirty Years'' War. A Swedish army under Gustavus Adolphus, supported by troops from Saxony and Hesse-Kassel, narrowly defeated an Imperial force under Albrecht von Wallenstein.', 1632, 11, 16, NULL, NULL, NULL, 'day', '16 November 1632', 69, 'https://en.wikipedia.org/wiki/Battle_of_L%C3%BCtzen_(1632)'),
  ('Q312212', 'Battle of Nördlingen', 'The Battle of Nördlingen, fought over two days from 5 to 6 September 1634, was a major battle of the Thirty Years'' War. An Imperial–Spanish force led by the Cardinal-Infante Ferdinand and Ferdinand of Hungary inflicted a crushing defeat on the Swedish–German army led by Gustav Horn and Bernhard of Saxe-Weimar.', 1634, 9, 5, 1634, 9, 6, 'day', '5 September 1634 – 6 September 1634', 63, 'https://en.wikipedia.org/wiki/Battle_of_N%C3%B6rdlingen_(1634)'),
  ('Q154635', 'Battle of Blenheim', 'The Battle of Blenheim (German: Zweite Schlacht bei Höchstädt; French: Bataille de Höchstädt; Dutch: Slag bij Blenheim) fought on 13 August [O.S. 2 August] 1704, was a major battle of the War of the Spanish Succession. The overwhelming Allied victory ensured the safety of Vienna from the Franco-Bavarian army, thus preventing the collapse of the reconstituted Grand Alliance.', 1704, 8, 13, NULL, NULL, NULL, 'day', '13 August 1704', 71, 'https://en.wikipedia.org/wiki/Battle_of_Blenheim'),
  ('Q696945', 'Battle of Schellenberg', 'The Battle of Schellenberg took place on 2 July 1704 during the War of the Spanish Succession. The engagement was part of the Duke of Marlborough''s campaign to save the Habsburg capital of Vienna from a threatened advance by King Louis XIV''s Franco-Bavarian forces ranged in southern Germany.', 1704, 7, 2, NULL, NULL, NULL, 'day', '2 July 1704', 59, 'https://en.wikipedia.org/wiki/Battle_of_Schellenberg'),
  ('Q402312', 'Battle of Dettingen', 'The Battle of Dettingen took place on 27 June 1743 during the War of the Austrian Succession, near Karlstein am Main in Bavaria. An alliance composed of British, Hanoverian and Austrian troops, known as the Pragmatic Army, defeated a French force commanded by the Duke of Noailles.', 1743, 6, 27, NULL, NULL, NULL, 'day', '27 June 1743', 61, 'https://en.wikipedia.org/wiki/Battle_of_Dettingen'),
  ('Q156086', 'Treaty of Aix-la-Chapelle', 'The 1748 Treaty of Aix-la-Chapelle, sometimes called the Treaty of Aachen, ended the War of the Austrian Succession, following a congress assembled on 24 April 1748 at the Free Imperial City of Aachen. The two main antagonists in the war, Britain and France, opened peace talks in the Dutch city of Breda in 1746.', 1748, 10, 18, NULL, NULL, NULL, 'day', '18 October 1748', 72, 'https://en.wikipedia.org/wiki/Treaty_of_Aix-la-Chapelle_(1748)'),
  ('Q573972', 'Battle of Rossbach', 'The Battle of Rossbach took place on 5 November 1757 during the Third Silesian War (1756–1763, part of the Seven Years'' War) near the village of Rossbach (Roßbach), in the Electorate of Saxony. It is sometimes called the Battle of, or at, Reichardtswerben, after a different nearby town.', 1757, 11, 5, NULL, NULL, NULL, 'day', '5 November 1757', 65, 'https://en.wikipedia.org/wiki/Battle_of_Rossbach'),
  ('Q698686', 'Treaty of Hubertusburg', 'The Treaty of Hubertusburg (German: Frieden von Hubertusburg) was signed on 15 February 1763 at Hubertusburg Castle by Prussia, Austria and Saxony to end the Third Silesian War. Together with the Treaty of Paris, signed five days earlier, it marked the end of the Seven Years'' War.', 1763, 2, 15, NULL, NULL, NULL, 'day', '15 February 1763', 65, 'https://en.wikipedia.org/wiki/Treaty_of_Hubertusburg'),
  ('Q705813', 'Battle of Hohenlinden', 'The Battle of Hohenlinden was fought on 3 December 1800 during the French Revolutionary Wars. A French army under Jean Victor Marie Moreau won a decisive victory over an Austrian and Bavarian force led by 18-year-old Archduke John of Austria.', 1800, 12, 3, NULL, NULL, NULL, 'day', '3 December 1800', 64, 'https://en.wikipedia.org/wiki/Battle_of_Hohenlinden'),
  ('Q159072', 'Battle of Ulm', 'The Battle of Ulm on 16–20 October 1805 was a series of skirmishes, at the end of the Ulm campaign, which allowed Napoleon I to trap an entire Austrian army under the command of Karl Freiherr Mack von Leiberich with minimal losses and to force its surrender near Ulm in the Electorate of Bavaria.', 1805, 10, 20, 1805, 10, 19, 'day', '20 October 1805 – 19 October 1805', 67, 'https://en.wikipedia.org/wiki/Battle_of_Ulm'),
  ('Q154426', 'Battle of Jena–Auerstedt', 'The Battle of Jena–Auerstedt was fought on Tuesday 14 October 1806, near Jena and Auerstedt (then in the Duchy of Saxe-Weimar and Kingdom of Prussia, now in Thuringia and Saxony-Anhalt, Germany), being the decisive engagement of the War of the Fourth Coalition. The Grande Armée under the command of Emperor Napoleon I defeated a combined Prussian and Saxon army.', 1806, 10, 14, NULL, NULL, NULL, 'day', '14 October 1806', 74, 'https://en.wikipedia.org/wiki/Battle_of_Jena%E2%80%93Auerstedt'),
  ('Q17594', 'Battle of Dresden', 'The Battle of Dresden (26–27 August 1813) was a major engagement of the Napoleonic Wars. The battle took place around the city of Dresden in modern-day Germany, then the capital of the Kingdom of Saxony.', 1813, 8, 26, 1813, 8, 27, 'day', '26 August 1813 – 27 August 1813', 64, 'https://en.wikipedia.org/wiki/Battle_of_Dresden'),
  ('Q151005', 'Battle of Leipzig', 'The Battle of Leipzig, also known as the Battle of the Nations, was fought from 16 to 19 October 1813 at Leipzig, Saxony. The Coalition armies of Austria, Prussia, Sweden, and Russia, led by Tsar Alexander I, Karl von Schwarzenberg, Gebhard von Blücher and Swedish Crown Prince Charles John, decisively defeated the Grande Armée of French Emperor Napoleon Bonaparte.', 1813, 10, 16, 1813, 10, 19, 'day', '16 October 1813 – 19 October 1813', 79, 'https://en.wikipedia.org/wiki/Battle_of_Leipzig'),
  ('Q170265', 'Battle of Bautzen', 'In the Battle of Bautzen (20–21 May 1813), a combined Prusso-Russian army, retreating after their defeat at Lützen and massively outnumbered, was pushed back by Napoleon but escaped destruction. Some sources claim that Marshal Michel Ney failed to block their retreat.', 1813, 5, 20, 1813, 5, 21, 'day', '20 May 1813 – 21 May 1813', 61, 'https://en.wikipedia.org/wiki/Battle_of_Bautzen_(1813)'),
  ('Q329534', 'Battle of Lützen', 'The Battle of Lützen, fought on 2 May 1813 near the town of Lützen in Saxony, was a major engagement during the War of the Sixth Coalition. It pitted Napoleon Bonaparte''s French forces against a coalition army of Prussian and Russian troops commanded by Generals Wittgenstein and Blücher.', 1813, 5, 2, NULL, NULL, NULL, 'day', '2 May 1813', 65, 'https://en.wikipedia.org/wiki/Battle_of_L%C3%BCtzen_(1813)'),
  ('Q156556', 'Treaty of Kiel', 'The Treaty of Kiel (Danish: Kieltraktaten) or Peace of Kiel (Swedish and Norwegian: Kielfreden or freden i Kiel) was concluded between the United Kingdom of Great Britain and Ireland and the Kingdom of Sweden on one side and the Kingdoms of Denmark and Norway on the other side on 14 January 1814 in Kiel. It ended the hostilities between the parties in the ongoing Napoleonic Wars, where the United Kingdom and Sweden were part of the anti-French alliance (the Sixth Coalition) while Denmark–Norway was allied to the French Empire.', 1814, 1, 14, NULL, NULL, NULL, 'day', '14 January 1814', 72, 'https://en.wikipedia.org/wiki/Treaty_of_Kiel'),
  ('Q158021', 'Treaty of Frankfurt', 'The Treaty of Frankfurt (French: Traité de Francfort; German: Friede von Frankfurt) was a peace treaty signed in Frankfurt on 10 May 1871 by the German Empire and the French Third Republic, at the end of the Franco-Prussian War.', 1871, 11, 7, NULL, NULL, NULL, 'day', '7 November 1871', 72, 'https://en.wikipedia.org/wiki/Treaty_of_Frankfurt_(1871)'),
  ('Q705537', 'Heligoland–Zanzibar Treaty', 'The Heligoland–Zanzibar Treaty (German: Helgoland-Sansibar-Vertrag; also known as the Anglo-German Agreement of 1890) was an agreement signed on 1 July 1890 between Germany and the United Kingdom. The accord gave Germany control of the Caprivi Strip (a ribbon of land that gave German South-West Africa access to the Zambezi River), the strategically located archipelago of Heligoland in the North Sea, and the heartland of German East Africa.', 1890, 7, 1, NULL, NULL, NULL, 'day', '1 July 1890', 61, 'https://en.wikipedia.org/wiki/Heligoland%E2%80%93Zanzibar_Treaty'),
  ('Q328271', 'Machtergreifung', 'The rise to power of Adolf Hitler, the dictator of Germany during the Nazi era from 1933 until his suicide in 1945, began in the newly established Weimar Republic in September 1919, when Hitler joined the Deutsche Arbeiterpartei (DAP; German Workers'' Party). He quickly rose to a place of prominence and became one of its most popular speakers.', 1933, 1, 30, NULL, NULL, NULL, 'day', '30 January 1933', 66, 'https://en.wikipedia.org/wiki/Nazi_seizure_of_power'),
  ('Q126413', 'German–Polish declaration of non-aggression', 'The German–Polish declaration of non-aggression, also known as the German–Polish non-aggression pact, was an agreement between Nazi Germany and the Second Polish Republic that was signed on 26 January 1934 in Berlin. Both countries pledged to resolve their problems by bilateral negotiations and to forgo armed conflict for a period of 10 years.', 1934, 1, 26, 1939, 4, 28, 'day', '26 January 1934 – 28 April 1939', 68, 'https://en.wikipedia.org/wiki/German%E2%80%93Polish_declaration_of_non-aggression'),
  ('Q154255', 'Munich agreement', 'The Munich Agreement was reached in Munich on 30 September 1938, by Nazi Germany, the United Kingdom, France, and Italy. The agreement provided for the German annexation of part of the First Czechoslovak Republic called the Sudetenland, where three million people, mainly ethnic Germans, lived.', 1938, 9, 30, NULL, NULL, NULL, 'day', '30 September 1938', 83, 'https://en.wikipedia.org/wiki/Munich_Agreement'),
  ('Q190882', 'Phoney War', 'The Phoney War was an eight-month period at the outset of World War II, lasting from September 1939 to May 1940, during which there were virtually no major Allied military land operations on the Western Front. World War II began on 1 September 1939 with Germany''s invasion of Poland.', 1939, 9, 3, 1940, 4, 10, 'day', '3 September 1939 – 10 April 1940', 77, 'https://en.wikipedia.org/wiki/Phoney_War'),
  ('Q713519', 'Saar Offensive', 'The Saar Offensive was the French invasion of Saarland, Germany, in the first stages of World War II, from September 7 to October 16, 1939, in response to the German invasion of Poland on 1 September 1939. The original plans called for 40 divisions, one armored division, three mechanised divisions, 78 artillery regiments and 40 tank battalions to assist Poland, which was then under invasion, by attacking Germany''s neglected western front.', 1939, 9, 7, 1939, 9, 16, 'day', '7 September 1939 – 16 September 1939', 68, 'https://en.wikipedia.org/wiki/Saar_Offensive'),
  ('Q162287', 'Battle of Hürtgen Forest', 'The Battle of Hürtgen Forest (German: Schlacht im Hürtgenwald) was a series of battles fought from 19 September to 16 December 1944, between American and German forces on the Western Front during World War II, in the Hürtgen Forest, a 140 km2 (54 mi2) area about 5 km (3.1 mi) east of the Belgian–German border. Lasting 88 days, it was the longest battle on German ground during World War II and it is the second longest single battle the U.S. Army has ever fought after the three-month-long Battle of Bataan.', 1944, 9, 14, 1945, 2, 10, 'day', '14 September 1944 – 10 February 1945', 67, 'https://en.wikipedia.org/wiki/Battle_of_H%C3%BCrtgen_Forest'),
  ('Q327052', 'Battle of Aachen', 'The Battle of Aachen was a battle of World War II, fought by American and German forces in and around Aachen, Germany, between 12 September and 21 October 1944. The city had been incorporated into the Siegfried Line, the main defensive network on Germany''s western border; the Allies had hoped to capture it quickly and advance into the industrialized Ruhr basin.', 1944, 10, 2, 1944, 10, 21, 'day', '2 October 1944 – 21 October 1944', 71, 'https://en.wikipedia.org/wiki/Battle_of_Aachen'),
  ('Q151187', 'Potsdam Conference', 'The Potsdam Conference (German: Potsdamer Konferenz) was held at Potsdam in the Soviet occupation zone from 17 July to 2 August 1945, to allow the three leading Allies to plan the postwar peace, while avoiding the mistakes of the Paris Peace Conference of 1919. The participants were the Soviet Union, the United Kingdom, and the United States.', 1945, 7, 17, 1945, 8, 2, 'day', '17 July 1945 – 2 August 1945', 82, 'https://en.wikipedia.org/wiki/Potsdam_Conference'),
  ('Q154182', 'Battle of Berlin', 'The Battle of Berlin, designated as the Berlin Strategic Offensive Operation by the Soviet Union, and also known as the Fall of Berlin, was one of the last major offensives of the European theatre of World War II. After the Vistula–Oder Offensive of January–February 1945, the Red Army had temporarily halted on a line 60 km (37 mi) east of Berlin. On 9 March, Germany established its defence plan for the city with Operation Clausewitz.', 1945, 4, 16, 1945, 5, 2, 'day', '16 April 1945 – 2 May 1945', 81, 'https://en.wikipedia.org/wiki/Battle_of_Berlin'),
  ('Q163244', 'Potsdam Declaration', 'The Potsdam Declaration, or the Proclamation Defining Terms for Japanese Surrender, was a statement that called for the surrender of all Japanese armed forces during World War II. On July 26, 1945, United States president Harry S. Truman, United Kingdom prime minister Winston Churchill, and President of China Chiang Kai-shek issued the document, which outlined the terms of surrender for the Empire of Japan, as agreed upon at the Potsdam Conference.', 1945, 7, 26, NULL, NULL, NULL, 'day', '26 July 1945', 72, 'https://en.wikipedia.org/wiki/Potsdam_Declaration'),
  ('Q699093', 'Ruhr Pocket', 'The Ruhr pocket was a battle of encirclement that took place in April 1945, on the Western Front near the end of World War II in Europe, in the Ruhr Area of Germany. Some 317,000 German troops were taken prisoner along with 24 generals.', 1945, 4, 18, NULL, NULL, NULL, 'day', '18 April 1945', 62, 'https://en.wikipedia.org/wiki/Ruhr_pocket'),
  ('Q7879625', 'Battle of the Seelow Heights', 'The Battle of the Seelow Heights (German: Schlacht um die Seelower Höhen) was part of the Berlin Strategic Offensive Operation (16 April – 2 May 1945). A pitched battle, it was one of the last assaults on large entrenched defensive positions of the Second World War.', 1945, 4, 16, 1945, 4, 19, 'day', '16 April 1945 – 19 April 1945', 63, 'https://en.wikipedia.org/wiki/Battle_of_the_Seelow_Heights'),
  ('Q512451', 'Occupation statute', 'The Occupation Statute of Germany (German: Besatzungsstatut) of April 10, 1949 specified the roles and responsibilities of the newly created government of the Federal Republic of Germany (West Germany) and the Allied High Commission. It was drawn up by American, British, and French representatives and was in force until the Treaties of Paris (1954) came into force on May 5, 1955.', 1949, 4, 8, 1955, 5, 5, 'day', '8 April 1949 – 5 May 1955', 48, 'https://en.wikipedia.org/wiki/Occupation_statute'),
  ('Q157682', 'East German uprising of 1953', 'The East German uprising of 1953 (German: Volksaufstand vom 17. Juni 1953) was an uprising that occurred over the course of two days in German Democratic Republic (GDR) from 16 to 17 June 1953.', 1953, 6, 16, 1953, 6, 17, 'day', '16 June 1953 – 17 June 1953', 72, 'https://en.wikipedia.org/wiki/East_German_uprising_of_1953'),
  ('Q708321', 'Berlin Crisis of 1961', 'The Berlin Crisis of 1961 (German: Berlin-Krise) was the last major European political and military incident of the Cold War concerning the status of the German capital city, Berlin, and of post–World War II Germany. The crisis culminated in the city''s de facto partition by the East German erection of the Berlin Wall.', 1961, 6, 4, 1961, 11, 9, 'day', '4 June 1961 – 9 November 1961', 66, 'https://en.wikipedia.org/wiki/Berlin_Crisis_of_1961'),
  ('Q274811', 'Élysée Treaty', 'The Élysée Treaty was a treaty of friendship between France and West Germany, signed by President Charles de Gaulle and Chancellor Konrad Adenauer on 22 January 1963 at the Élysée Palace in Paris. With the signing of this treaty, Germany and France established a new foundation for relations, bringing an end to centuries of French–German enmity and wars.', 1963, 1, 22, NULL, NULL, NULL, 'day', '22 January 1963', 68, 'https://en.wikipedia.org/wiki/%C3%89lys%C3%A9e_Treaty'),
  ('Q186444', 'Treaty on the Non-Proliferation of Nuclear Weapons', 'The Treaty on the Non-Proliferation of Nuclear Weapons, commonly known as the Non-Proliferation Treaty or NPT, is an international treaty, the objective of which is to prevent the spread of nuclear weapons and weapons technology, to promote cooperation in the peaceful uses of nuclear energy, and to further the goal of achieving nuclear disarmament and general and complete disarmament. Between 1965 and 1968, the treaty was negotiated by the Eighteen Nation Committee on Disarmament, a United Nations-sponsored organization based in Geneva, Switzerland.', 1968, 7, 1, NULL, NULL, NULL, 'day', '1 July 1968', 83, 'https://en.wikipedia.org/wiki/Treaty_on_the_Non-Proliferation_of_Nuclear_Weapons'),
  ('Q8438', '1972 Summer Olympics', 'The 1972 Summer Olympics (German: Olympische Sommerspiele 1972), officially known as the Games of the XX Olympiad (German: Spiele der XX. Olympiade) and officially branded as Munich 1972 (German: München 1972; Bavarian: Minga 1972), were an international multi-sport event held in Munich, West Germany, from 26 August to 11 September 1972. It was the second Summer Olympics to be held in Germany, after the 1936 Games in Berlin, which had taken place under the Nazi rule.', 1972, NULL, NULL, 1972, 9, 11, 'year', '1972', 85, 'https://en.wikipedia.org/wiki/1972_Summer_Olympics'),
  ('Q672112', 'Basic Treaty', 'The Basic Treaty (German: Grundlagenvertrag, pronounced [ˈɡʁʊntlaːɡn̩fɛɐ̯ˌtʁaːk] ) is the shorthand name for the Treaty concerning the basis of relations between the Federal Republic of Germany and the German Democratic Republic (German: Vertrag über die Grundlagen der Beziehungen zwischen der Bundesrepublik Deutschland und der Deutschen Demokratischen Republik). The Federal Republic of Germany and German Democratic Republic (GDR) recognized each other as sovereign states for the first time, an abandonment of West Germany''s Hallstein Doctrine in favor of Ostpolitik.', 1972, 12, 21, 1990, 10, 3, 'day', '21 December 1972 – 3 October 1990', 55, 'https://en.wikipedia.org/wiki/Basic_Treaty%2C_1972'),
  ('Q125371', 'Bonn Convention', 'The Convention on the Conservation of Migratory Species of Wild Animals, also known as the Convention on Migratory Species (CMS) or the Bonn Convention, is an international agreement that aims to conserve migratory species throughout their ranges. The agreement was signed under the auspices of the United Nations Environment Programme and is concerned with conservation of wildlife and habitats on a global scale.', 1979, NULL, NULL, NULL, NULL, NULL, 'year', '1979', 64, 'https://en.wikipedia.org/wiki/Convention_on_the_Conservation_of_Migratory_Species_of_Wild_Animals'),
  ('Q314087', 'Ramstein air show disaster', 'On 28 August 1988, three aircraft of the Italian Air Force display team collided during the Flugtag ''88 airshow at USAF Ramstein Air Base near Kaiserslautern, West Germany. They crashed to the ground in front of a crowd of about 300,000 people, causing 70 fatalities (67 spectators and 3 pilots); 346 spectators sustained serious injuries in the resulting explosion and fire.', 1988, 8, 28, NULL, NULL, NULL, 'day', '28 August 1988', 63, 'https://en.wikipedia.org/wiki/Ramstein_air_show_disaster'),
  ('Q159644', 'Treaty on the Final Settlement with Respect to Germany', 'The Treaty on the Final Settlement with Respect to Germany (German: Vertrag über die abschließende Regelung in Bezug auf Deutschland), more commonly referred to as the Two Plus Four Agreement (Zwei-plus-Vier-Vertrag), is an international agreement that allowed the reunification of Germany in October 1990. It was negotiated in 1990 between the ''two'', the Federal Republic of Germany and the German Democratic Republic, in addition to the Four Powers which had occupied Germany at the end of World War II in Europe: France, the Soviet Union, the United Kingdom, and the United States.', 1990, 9, 12, NULL, NULL, NULL, 'day', '12 September 1990', 71, 'https://en.wikipedia.org/wiki/Treaty_on_the_Final_Settlement_with_Respect_to_Germany'),
  ('Q56039', 'German reunification', 'German reunification (German: Deutsche Wiedervereinigung), also known as the expansion of the Federal Republic of Germany (BRD), was the process of re-establishing Germany as a single sovereign state, which began on 9 November 1989 and culminated on 3 October 1990 with the dissolution of the German Democratic Republic and the integration of its re-established constituent federated states into the Federal Republic of Germany to form present-day Germany. This date was chosen as the customary German Unity Day, and has thereafter been celebrated each year as a national holiday.', 1991, 3, 15, NULL, NULL, NULL, 'day', '15 March 1991', 85, 'https://en.wikipedia.org/wiki/German_reunification'),
  ('Q242352', 'Yugoslav Wars', 'The Yugoslav Wars were a series of separate but related ethnic conflicts, wars of independence, and insurgencies that took place from 1991 to 2001 in what had been the Socialist Federal Republic of Yugoslavia. The conflicts both led up to and resulted from the breakup of Yugoslavia, which began in mid-1991, into six independent countries matching the six republics that had previously constituted Yugoslavia: Slovenia, Croatia, Bosnia and Herzegovina, Montenegro, Serbia, and Macedonia, which was later renamed to North Macedonia.', 1991, 3, 31, 2001, 8, 13, 'day', '31 March 1991 – 13 August 2001', 79, 'https://en.wikipedia.org/wiki/Yugoslav_Wars'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q163107', 'Überlingen mid-air collision', 'On 1 July 2002, BAL Bashkirian Airlines Flight 2937, a Tupolev Tu-154 passenger jet, and DHL International Aviation ME Flight 611, a Boeing 757 cargo jet, collided in mid-air over Überlingen, a southern German town on Lake Constance, near the German-Swiss border. All of the passengers and crew aboard both planes were killed, resulting in a total death toll of 71 including 52 children.', 2002, 7, 1, NULL, NULL, NULL, 'day', '1 July 2002', 67, 'https://en.wikipedia.org/wiki/2002_%C3%9Cberlingen_mid-air_collision'),
  ('Q28036573', '2016 Berlin attack', 'On 19 December 2016, a truck was deliberately driven into the Christmas market next to the Kaiser Wilhelm Memorial Church at Breitscheidplatz in Berlin, leaving 12 people dead and 56 others injured. One of the victims was the truck''s original driver, Łukasz Urban, who was shot dead hours before the attack.', 2016, 12, 19, NULL, NULL, NULL, 'day', '19 December 2016', 76, 'https://en.wikipedia.org/wiki/2016_Berlin_truck_attack'),
  ('Q58805164', 'Yellow vests movement', 'The yellow vest movement (French: Mouvement des gilets jaunes, pronounced [muvmɑ̃ de ʒilɛ ʒon]) refers to those involved in a series of populist, grassroots weekly protests in France that began on 17 November 2018 and ended on 28 June 2020. After an online petition posted in May 2018 had attracted nearly one million signatures, mass demonstrations began on 17 November.', 2018, 11, 17, NULL, NULL, NULL, 'day', '17 November 2018', 80, 'https://en.wikipedia.org/wiki/Yellow_vests_protests'),
  ('Q60727566', 'Treaty of Aachen', 'The Aachen Treaty, formally Treaty on Franco-German Cooperation and Integration, and also known as the Treaty of Aachen (German: Aachener Vertrag, Vertrag von Aachen, French: Traité d''Aix-la-Chapelle), is a bilateral agreement between Germany and France concerning mutual cooperation across major subjects, which entered into force on 22 January 2020, a year after it was signed. It was signed by Federal Chancellor Angela Merkel and President Emmanuel Macron in the coronation hall of the Aachen City Hall on 22 January 2019.', 2019, 1, 22, NULL, NULL, NULL, 'day', '22 January 2019', 60, 'https://en.wikipedia.org/wiki/Aachen_Treaty'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods');
